export async function updateDocument(input: {
  id: string
  content: string
  expectedVersion: number
}) {

output:

  const { id, content, expectedVersion } = input

  try {
    // Attempt to update the document with an optimistic concurrency check
    await prisma.document.update({
      where: {
        id,
        version: expectedVersion, // Ensure the document has not been updated by another process since it was read
      },
      data: {
        content,
        version: expectedVersion + 1, // Increment the version to indicate an update
      },
    })

    return { success: true }
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === 'P2003') {
      // P2003 indicates that no rows were updated, which means the document was already updated by another process
      return { success: false, message: 'Document has been updated by another process' }
    } else {
      throw error
    }
  }
}

