'use client'
import { useState, useOptimistic } from 'react'
import { addComment } from '@/app/actions/comment/add'

interface Comment { id: string; body: string; authorName: string; createdAt: Date }

export default function CommentThread({ postId, initialComments }: { postId: string; initialComments: Comment[] }) {

output:
  const [comments, setComments] = useState<Comment[]>(initialComments)
  const [newCommentBody, setNewCommentBody] = useState<string>('')

  // Optimistic update to handle the comment addition immediately
  const [optimisticComments, addOptimisticComment] = useOptimistic<Comment[], Comment>(
    comments,
    (state, newComment) => [...state, newComment]
  )

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    if (!newCommentBody.trim()) return

    // Optimistically add the comment
    addOptimisticComment({ id: Date.now().toString(), body: newCommentBody, authorName: 'Anonymous', createdAt: new Date() })

    try {
      const response = await addComment(postId, { body: newCommentBody })
      if (response.success) {
        // Update the state with the actual comment data
        setComments((prevComments) => [...prevComments, response.data])
      } else {
        console.error('Failed to add comment:', response.message)
      }
    } catch (error) {
      console.error('Error adding comment:', error)
    }

    // Clear the input field after submission
    setNewCommentBody('')
  }

  return (
    <div>
      <h2>Comments</h2>
      <form onSubmit={handleSubmit}>
        <textarea value={newCommentBody} onChange={(e) => setNewCommentBody(e.target.value)} placeholder="Add a comment..." />
        <button type="submit">Submit</button>
      </form>

      {/* Display comments */}
      {optimisticComments.map((comment) => (
        <div key={comment.id}>
          <p>{comment.body}</p>
          <p>By {comment.authorName} on {comment.createdAt.toLocaleString()}</p>
        </div>
      ))}
    </div>
  )
}

