// app/deals/page.tsx
import { prisma } from '@/lib/prisma'

interface PageProps {
  searchParams: { q?: string; page?: string; sort?: string }
}

export default async function DealsPage({ searchParams }: PageProps) {

output:

  const query = searchParams.q || ''
  const page = parseInt(searchParams.page || '1', 10)
  const sort = searchParams.sort || 'createdAt'

  // Fetch deals from the database
  const deals = await prisma.deal.findMany({
    where: {
      title: { contains: query, mode: 'insensitive' },
    },
    orderBy: {
      [sort]: 'desc',
    },
    skip: (page - 1) * 10,
    take: 10,
  })

  // Fetch total count of deals
  const totalCount = await prisma.deal.count({
    where: {
      title: { contains: query, mode: 'insensitive' },
    },
  })

  return (
    <div>
      <h1>Deals</h1>
      <ul>
        {deals.map((deal) => (
          <li key={deal.id}>{deal.title}</li>
        ))}
      </ul>
      <nav>
        <button disabled={page === 1}>Previous</button>
        <span>{page} of {Math.ceil(totalCount / 10)}</span>
        <button disabled={page * 10 >= totalCount}>Next</button>
      </nav>
    </div>
  )
}
```

This code defines a `DealsPage` component that fetches deals from the database based on search parameters such as query, page number, and sort order. It then displays the deals in a list and provides navigation buttons to move between pages.

The `prisma.deal.findMany` method is used to retrieve deals that match the search query, ordered by the specified field. The `skip` and `take` options are used to paginate the results based on the current page number.

The `prisma.deal.count` method is used to fetch the total count of deals that match the search query, which is then used to calculate the total number of pages.

Finally, the component renders a list of deals and navigation buttons to move between pages. The navigation buttons are disabled when there are no more pages to navigate to.

