'use server'
import Stripe from 'stripe'
import { prisma } from '@/lib/prisma'

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!)

export async function ensureStripeCustomer(userId: string, email: string) {

output:

  // Check if the user already has a Stripe customer ID in the database
  const existingCustomer = await prisma.user.findUnique({
    where: {
      id: userId,
    },
    select: {
      stripeCustomerId: true,
    },
  })

  if (existingCustomer?.stripeCustomerId) {
    return existingCustomer.stripeCustomerId
  }

  // If no customer ID exists, create a new one in Stripe
  const customer = await stripe.customers.create({
    email,
  })

  // Store the new customer ID in the database
  await prisma.user.update({
    where: {
      id: userId,
    },
    data: {
      stripeCustomerId: customer.id,
    },
  })

  return customer.id
}

