      {isOpen && (
        <ul className="absolute mt-2 bg-white border rounded shadow-lg w-full z-10">
          {items.map((item, index) => (
            <li
              key={index}
              onClick={() => {
                item.onSelect()
                setIsOpen(false)
              }}
              className="px-4 py-2 hover:bg-gray-100 cursor-pointer"
            >
              {item.label}
            </li>
          ))}
        </ul>
      )}
