import { z } from 'zod'
import { prisma } from '@/lib/db'

const InviteAction = z.object({
  type: z.literal('invite'),
  email: z.string().email(),
  role: z.enum(['admin', 'member']),
})

const RemoveAction = z.object({
  type: z.literal('remove'),
  userId: z.string(),
})

