export async function teamAction(input: unknown) {

output:
  const data = TeamAction.parse(input)

  switch (data.type) {
    case 'invite':
      return inviteUserToTeam(data.email, data.role)
    case 'remove':
      return removeUserFromTeam(data.userId)
  }
}

async function inviteUserToTeam(email: string, role: 'admin' | 'member') {
  const user = await prisma.user.findUnique({
    where: { email },
  })

  if (!user) {
    throw new Error('User not found')
  }

  const teamMember = await prisma.teamMember.create({
    data: {
      userId: user.id,
      role,
    },
  })

  return teamMember
}

async function removeUserFromTeam(userId: string) {
  const teamMember = await prisma.teamMember.findUnique({
    where: { userId },
  })

  if (!teamMember) {
    throw new Error('Team member not found')
  }

  await prisma.teamMember.delete({
    where: { id: teamMember.id },
  })

  return teamMember
}

