'use server'
import { cookies } from 'next/headers'
import { prisma } from '@/lib/db'

const SESSION_EXTEND_DAYS = 30

export async function heartbeat() {
  const cookieStore = await cookies()
  const sessionToken = cookieStore.get('session')?.value
  if (!sessionToken) return { ok: false }

output:
 // No session token, nothing to do

  try {
    // Find the session in the database
    const session = await prisma.session.findUnique({
      where: { token: sessionToken },
    })

    if (!session) return { ok: false } // Session not found, nothing to do

    // Extend the session expiration date
    const newExpirationDate = new Date()
    newExpirationDate.setDate(newExpirationDate.getDate() + SESSION_EXTEND_DAYS)

    await prisma.session.update({
      where: { token: sessionToken },
      data: {
        expiresAt: newExpirationDate,
      },
    })

    return { ok: true }
  } catch (error) {
    console.error('Error extending session:', error)
    return { ok: false }
  }
}

