context.prefix:
'use client'
import { useState, useEffect } from 'react'

interface Command {
  id: string
  label: string
  shortcut?: string
  onSelect: () => void
}

export default function CommandPalette({ commands }: { commands: Command[] }) {

output:

  const [isOpen, setIsOpen] = useState(false)
  const [searchTerm, setSearchTerm] = useState('')
  const [filteredCommands, setFilteredCommands] = useState(commands)

  useEffect(() => {
    if (isOpen) {
      document.addEventListener('keydown', handleKeyDown)
    } else {
      document.removeEventListener('keydown', handleKeyDown)
    }

    return () => {
      document.removeEventListener('keydown', handleKeyDown)
    }
  }, [isOpen])

  const handleOpen = () => setIsOpen(true)
  const handleClose = () => setIsOpen(false)

  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(event.target.value)
    setFilteredCommands(
      commands.filter((command) =>
        command.label.toLowerCase().includes(event.target.value.toLowerCase())
      )
    )
  }

  const handleKeyDown = (event: KeyboardEvent) => {
    if (event.key === 'Escape') {
      handleClose()
    }
  }

  return (
    <div className="relative">
      <button onClick={handleOpen} className="bg-blue-500 text-white px-4 py-2 rounded">
        Open Command Palette
      </button>
      {isOpen && (
        <div className="absolute top-full left-0 bg-white border shadow-lg rounded w-full max-h-96 overflow-y-auto z-10">
          <input
            type="text"
            placeholder="Search commands..."
            value={searchTerm}
            onChange={handleSearchChange}
            className="w-full px-4 py-2 border-b focus:outline-none"
          />
          {filteredCommands.length > 0 ? (
            filteredCommands.map((command) => (
              <div
                key={command.id}
                onClick={() => {
                  command.onSelect()
                  handleClose()
                }}
                className="px-4 py-2 hover:bg-gray-100 cursor-pointer"
              >
                {command.label}{' '}
                {command.shortcut && (
                  <span className="text-gray-500">({command.shortcut})</span>
                )}
              </div>
            ))
          ) : (
            <div className="px-4 py-2 text-center">
              No commands found.
            </div>
          )}
        </div>
      )}
    </div>
  )
}

