  private listeners: Partial<Record<keyof E, Array<(arg: E[keyof E]) => void>>> = {}

  on<K extends keyof E>(event: K, listener: (arg: E[K]) => void): this {
    if (!this.listeners[event]) {
      this.listeners[event] = []
    }
    this.listeners[event]?.push(listener)
    return this
  }

  off<K extends keyof E>(event: K, listener: (arg: E[K]) => void): this {
    const listeners = this.listeners[event]
    if (listeners) {
      const index = listeners.indexOf(listener)
      if (index !== -1) {
        listeners.splice(index, 1)
      }
    }
    return this
  }

  emit<K extends keyof E>(event: K, arg: E[K]): boolean {
    const listeners = this.listeners[event]
    if (listeners && listeners.length > 0) {
      for (const listener of listeners) {
        listener(arg)
      }
      return true
    }
    return false
  }

  once<K extends keyof E>(event: K, listener: (arg: E[K]) => void): this {
    const wrapper = (arg: E[K]) => {
      listener(arg)
      this.off(event, wrapper)
    }
    this.on(event, wrapper)
    return this
  }
}

